    """Decode and validate a cursor for the given org.

    Raises ``InvalidCursor`` on any failure: undecodable garbage, bad
    signature, unknown version, or a cursor minted for another org.
    """
    try:
        payload = json.loads(decrypt_text(cursor))
    except Exception:
        # Bad base64, bad signature, malformed JSON, ... all one stable code.
        raise InvalidCursor()
    if not isinstance(payload, dict):
        raise InvalidCursor()
    if payload.get("v") != CURSOR_VERSION:
        raise InvalidCursor()
    if payload.get("org") != org_id:
        raise InvalidCursor()
    end = payload.get("end")
    last = payload.get("last")
    if not isinstance(end, int) or isinstance(end, bool):
        raise InvalidCursor()
    if not isinstance(last, int) or isinstance(last, bool):
        raise InvalidCursor()
    if end < 0 or last < 0 or last > end:
        raise InvalidCursor()
    return {"end": end, "last": last}

